// Bóc giá dầu DO 0,05S từ HTML PVOIL.
// ⚠️ TODO KHI DEPLOY: selector/regex phụ thuộc cấu trúc trang tại thời điểm chạy —
// chạy thử 1 lần, xem HTML thật rồi chỉnh regex bên dưới cho khớp.
const html = $input.first().json.data || '';
// mẫu thường gặp: 'Dầu DO 0,05S ... 21.500' (đồng/lít, có thể có dấu chấm nghìn)
const m = html.match(/D[ầa]u\s*DO[^0-9]{0,40}([0-9]{2}[.,][0-9]{3})/i);
if (!m) {
  // KHÔNG ghi giá bịa — báo lỗi để error handler bắn cảnh báo.
  throw new Error('Không bóc được giá dầu DO từ trang PVOIL — cần chỉnh regex');
}
const price = parseInt(m[1].replace(/[.,]/g, ''), 10);
if (!price || price < 10000 || price > 60000) {
  throw new Error('Giá bóc được bất thường: ' + price + ' — không ghi');
}
return [{ json: {
  date: new Date().toISOString().slice(0, 10),
  fuel_type: 'diesel',
  price: price,
  source: 'pvoil.com.vn'
}}];
